-- 2. Add human-readable small unique ID (elevates_id) to chapters (Format: CHP-XXXXXX)
ALTER TABLE public.chapters
  ADD COLUMN IF NOT EXISTS elevates_id TEXT UNIQUE;

-- Helper function: generates a unique 6-char alphanumeric chapter token (letters & numbers)
CREATE OR REPLACE FUNCTION public.generate_chapter_elevates_id()
RETURNS TEXT LANGUAGE plpgsql AS $$
DECLARE
  chars  TEXT    := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; -- no 0/O/1/I confusion
  result TEXT    := '';
  i      INT;
  attempts INT   := 0;
BEGIN
  LOOP
    result := '';
    FOR i IN 1..6 LOOP
      result := result || substr(chars, floor(random() * length(chars) + 1)::INT, 1);
    END LOOP;
    -- Ensure uniqueness
    EXIT WHEN NOT EXISTS (SELECT 1 FROM public.chapters WHERE elevates_id = 'CHP-' || result);
    attempts := attempts + 1;
    IF attempts > 100 THEN
      RAISE EXCEPTION 'generate_chapter_elevates_id: too many collisions';
    END IF;
  END LOOP;
  RETURN 'CHP-' || result;
END;
$$;

-- Backfill existing chapters that don't have an elevates_id yet
UPDATE public.chapters
SET    elevates_id = public.generate_chapter_elevates_id()
WHERE  elevates_id IS NULL;

-- Index for fast lookup
CREATE INDEX IF NOT EXISTS idx_chapters_elevates_id ON public.chapters (elevates_id);

-- Trigger: auto-assign elevates_id on INSERT if not supplied
CREATE OR REPLACE FUNCTION public.assign_chapter_elevates_id()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.elevates_id IS NULL OR NEW.elevates_id = '' THEN
    NEW.elevates_id := public.generate_chapter_elevates_id();
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS before_chapter_insert_assign_elevates_id ON public.chapters;
CREATE TRIGGER before_chapter_insert_assign_elevates_id
  BEFORE INSERT ON public.chapters
  FOR EACH ROW EXECUTE FUNCTION public.assign_chapter_elevates_id();

-- 3. Seed or update the Elevates Test Chapter in public.chapters
-- Migrate old zero-id test chapter if present
UPDATE public.chapters
SET id = 'e1e7a050-7e57-4c8a-9b12-a1b2c3d4e5f6'
WHERE slug = 'test-chapter' AND id = '00000000-0000-0000-0000-000000000099';

